62	/* LoadingSpinner (flat) — Material's circular indeterminate dash, as two
63	 * numbers animated on the <svg> once per --ui-spinner-duration:
64	 *   --ds-spinner-grow  0 → 1 → 1   the arc's length, min → max sweep
65	 *   --ds-spinner-tail  0 → .118 → .985  where the arc's tail sits, in turns
66	 * Both arc paths compute their dashes from the same two values, so the arc
67	 * and the track cannot drift apart. Registered so the animation interpolates
68	 * numbers; inherited so the paths read the values animated on their <svg>. */
69	@property --ds-spinner-grow {
70	  syntax: "<number>";
